function checkSignup(email, slot, signups, memberEmails) {
  const cleanEmail = String(email ?? "").trim().toLowerCase()
  if (cleanEmail === "") {
    return { status: 400, error: "Email is required" }
  }
  if (!memberEmails.includes(cleanEmail)) {
    return { status: 400, error: "Not a club member" }
  }
  const forSlot = signups.filter(s => s.slotId === slot.id)
  if (forSlot.some(s => s.memberEmail === cleanEmail)) {
    return { status: 409, error: "Already signed up" }
  }
  if (forSlot.length >= slot.capacity) {
    return { status: 409, error: "Shift is full" }
  }
  return { status: 201 }
}
